function refreshStudentFilterOptions(){const keepDepartment=studentDepartmentFilter.value,keepYear=studentYearFilter.value,departments=[...new Set(allStudentRows.map(s=>String(s.department||"").trim()).filter(Boolean))].sort((a,b)=>a.localeCompare(b,"zh-Hant")),years=[...new Set(allStudentRows.map(s=>String(s.admissionYear||"").trim()).filter(Boolean))].sort((a,b)=>b.localeCompare(a,undefined,{numeric:true}));studentDepartmentFilter.innerHTML='<option value="all">全部科系</option>'+departments.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(x)}</option>`).join("");studentYearFilter.innerHTML='<option value="all">全部學年度</option>'+years.map(x=>`<option value="${escapeHtml(x)}">${escapeHtml(x)}學年度</option>`).join("");if(departments.includes(keepDepartment))studentDepartmentFilter.value=keepDepartment;if(years.includes(keepYear))studentYearFilter.value=keepYear}
function timestampValue(value){if(value?.toMillis)return value.toMillis();if(value?.seconds)return value.seconds*1000;const parsed=Date.parse(value);return Number.isFinite(parsed)?parsed:0}
function canTransferStudents(){const signedInEmail=normalizedEmail(auth.currentUser?.email),delegatedOwner=normalizedEmail(currentAccess?.ownerEmail);return currentAccess?.role!=="assistant"&&(!delegatedOwner||delegatedOwner===signedInEmail)}
function renderStudentList(){const keyword=studentSearchInput.value.trim().toLowerCase(),department=studentDepartmentFilter.value,year=studentYearFilter.value,stateFilter=studentStateFilter.value,sort=studentSortSelect.value;visibleStudentRows=allStudentRows.filter(s=>(!keyword||`${s.name||""} ${s.studentId||""}`.toLowerCase().includes(keyword))&&(department==="all"||s.department===department)&&(year==="all"||String(s.admissionYear)===year)&&(stateFilter==="all"||(stateFilter==="holding"?s.creditHolding===true:s.creditHolding!==true)));const collator=new Intl.Collator("zh-Hant",{numeric:true,sensitivity:"base"});visibleStudentRows.sort((a,b)=>{if(sort==="created-asc")return timestampValue(a.createdAt)-timestampValue(b.createdAt);if(sort==="name-asc")return collator.compare(a.name||"",b.name||"");if(sort==="id-asc")return collator.compare(a.studentId||"",b.studentId||"");if(sort==="year-asc")return collator.compare(String(a.admissionYear||""),String(b.admissionYear||""));if(sort==="year-desc")return collator.compare(String(b.admissionYear||""),String(a.admissionYear||""));return timestampValue(b.createdAt)-timestampValue(a.createdAt)});if(!allStudentRows.length){studentList.innerHTML='<div class="empty">目前尚未建立學生，請按右上角「新增學生」。</div>'}else if(!visibleStudentRows.length){studentList.innerHTML=`<div class="empty">${stateFilter==="holding"?"學分暫存區目前沒有學生。":"沒有符合搜尋或篩選條件的學生。"}</div>`}else{studentList.innerHTML=visibleStudentRows.map((s,i)=>`<article class="student-row"><label class="student-select" title="選取${escapeHtml(s.name)}"><input type="checkbox" class="student-checkbox" data-id="${escapeHtml(s.docId)}" ${selectedStudentIds.has(s.docId)?"checked":""} aria-label="選取${escapeHtml(s.name)}"></label><div><h3>${escapeHtml(s.name)}${s.creditHolding?'<span class="holding-chip">學分暫存</span>':""}</h3><p>${escapeHtml(s.studentId)}｜${escapeHtml(s.department)}｜${escapeHtml(s.admissionYear)}學年度入學｜目前${currentGradeLabel(s.admissionYear)}</p></div><div class="student-row-actions"><button class="primary open-real" data-index="${i}">查看學分</button><button class="small-button export-student" data-index="${i}">匯出 Excel</button><button class="small-button edit-student" data-index="${i}">修改</button>${canTransferStudents()?`<button class="small-button transfer-student" data-index="${i}">${s.creditHolding?"移出／轉移":"轉移"}</button>`:""}<button class="small-button danger delete-student" data-index="${i}">刪除</button></div></article>`).join("");document.querySelectorAll(".open-real").forEach(b=>b.onclick=()=>openManagedStudent(visibleStudentRows[Number(b.dataset.index)]));document.querySelectorAll(".export-student").forEach(b=>b.onclick=()=>exportStudentExcel(visibleStudentRows[Number(b.dataset.index)]));document.querySelectorAll(".edit-student").forEach(b=>b.onclick=()=>openStudentEditor(visibleStudentRows[Number(b.dataset.index)]));document.querySelectorAll(".transfer-student").forEach(b=>b.onclick=()=>openStudentTransfer(visibleStudentRows[Number(b.dataset.index)]));document.querySelectorAll(".delete-student").forEach(b=>b.onclick=()=>removeStudent(visibleStudentRows[Number(b.dataset.index)]));document.querySelectorAll(".student-checkbox").forEach(c=>c.onchange=()=>{c.checked?selectedStudentIds.add(c.dataset.id):selectedStudentIds.delete(c.dataset.id);updateBatchControls()})}updateBatchControls()}
function openManagedStudent(s){student=s;student.id=student.studentId;currentCurriculum=curricula.find(c=>c.docId===student.curriculumId)||null;targets=currentCurriculum?.targets||student.creditTargets||{"校必修":30,"院必修":18,"專業必修":47,"專業選修":33};student.courses=student.courses?.length?student.courses:structuredClone(currentCurriculum?.courses||[]);openStudent("teacher")}
