function openStudentEditor(s){editingStudent=s;fillCurriculumSelect();studentDialogTitle.textContent="修改學生";saveStudentBtn.textContent="儲存修改";studentNameInput.value=s.name||"";studentIdInput.value=s.studentId||"";studentIdInput.disabled=true;admissionYearInput.value=s.admissionYear||"";departmentInput.value=s.department||"";programInput.value=s.program||"";curriculumSelect.value=s.curriculumId||"";studentDialog.showModal()}
async function removeStudent(s){if(!confirm(`確定刪除學生「${s.name}（${s.studentId}）」？此操作會一併刪除其學分檢核資料。`))return;try{await deleteDoc(doc(db,"students",s.docId));await loadMyStudents()}catch(error){console.error(error);alert("刪除失敗，請確認權限。")}}
function normalizedName(name){return String(name||"").replace(/[\s　()（）【】\[\]·・,，.。]/g,"").toLowerCase()}
function coreCourseName(name){return String(name||"").replace(/[（(][^）)]*[）)]/g,"").replace(/[\s　【】\[\]·・,，.。]/g,"").toLowerCase()}
function withoutUndefined(value){return Object.fromEntries(Object.entries(value).filter(([,v])=>v!==undefined))}
function mergeCoursesForCurriculum(template,history){const remaining=[...history];const result=structuredClone(template).map(course=>{const i=remaining.findIndex(h=>normalizedName(h.name)===normalizedName(course.name));if(i<0)return course;const old=remaining.splice(i,1)[0];return withoutUndefined({...course,status:old.status,attemptTerm:old.attemptTerm,recognitionType:old.recognitionType,adjusted:old.adjusted,note:old.note})});remaining.filter(c=>["done","classified","failed","unmatched"].includes(c.status)).forEach(c=>result.push(withoutUndefined({...c,status:c.status==="failed"?"failed":"unmatched",previousCategory:c.category,category:null,note:[c.note,"更換時序表後需重新確認"].filter(Boolean).join("；")})));return result}
onAuthStateChanged(auth,user=>{if(!user)currentAccess=null;logoutBtn.classList.toggle("hidden",!user);systemBadge.textContent=user?`已登入：${user.email}`:"Firebase測試版"});

async function loadCurricula(){const ref=collection(db,"curricula");if(currentAccess?.role==="admin"){const snap=await getDocs(ref);curricula=snap.docs.map(d=>({docId:d.id,...d.data()})).filter(c=>!c.ownerEmail||normalizedEmail(c.ownerEmail)===workspaceOwnerEmail())}else{const snap=await getDocs(query(ref,where("ownerEmail","==",workspaceOwnerEmail())));curricula=snap.docs.map(d=>({docId:d.id,...d.data()}))}curricula.sort((a,b)=>String(b.admissionYear).localeCompare(String(a.admissionYear)))}
function fillCurriculumSelect(){curriculumSelect.innerHTML='<option value="">請選擇時序表</option>'+curricula.filter(c=>c.status==="ready").map(c=>`<option value="${c.docId}">${escapeHtml(c.admissionYear)}｜${escapeHtml(c.department)}｜${escapeHtml(c.program)}</option>`).join("")}
function renderCurricula(){curriculumList.innerHTML=curricula.length?curricula.map(c=>`<div class="curriculum-row"><div><strong>${escapeHtml(c.admissionYear)}學年度｜${escapeHtml(c.department)}｜${escapeHtml(c.program)}</strong><span>來源：${escapeHtml(c.sourceFileName||"未上傳")}｜課程${c.courses?.length||0}門${c.ownerEmail?"":"｜舊版資料，儲存後歸入我的工作區"}</span></div><div class="curriculum-actions"><span class="status-chip ${c.status==="ready"?"ready":"pending"}">${c.status==="ready"?"已啟用":"待辨識"}</span><button type="button" class="small-button edit-curriculum" data-id="${c.docId}">課程確認</button>${c.status!=="ready"?`<button type="button" class="small-button replace-curriculum" data-id="${c.docId}">更換PDF</button>`:""}<button type="button" class="small-button danger delete-curriculum" data-id="${c.docId}">刪除</button></div></div>`).join(""):'<div class="empty">你的工作區尚未建立時序表。</div>';document.querySelectorAll(".edit-curriculum").forEach(b=>b.onclick=()=>openCourseEditor(b.dataset.id));document.querySelectorAll(".replace-curriculum").forEach(b=>b.onclick=()=>replaceCurriculumPdf(b.dataset.id));document.querySelectorAll(".delete-curriculum").forEach(b=>b.onclick=()=>removeCurriculum(b.dataset.id))}
saveCurriculumBtn.onclick=async e=>{e.preventDefault();curriculumError.textContent="";try{const year=curriculumYear.value.trim(),department=curriculumDepartment.value.trim(),program=curriculumProgram.value.trim(),file=curriculumPdfInput.files[0];if(!year||!department||!program||!file){curriculumError.textContent="請完整填寫版本資料並選擇PDF。";return}if(file.type!=="application/pdf"){curriculumError.textContent="只接受PDF檔案。";return}const duplicate=curricula.some(c=>c.ownerEmail===workspaceOwnerEmail()&&c.admissionYear===year&&c.department===department&&c.program===program);if(duplicate){curriculumError.textContent="你的工作區已有相同入學年度、科系與學制的時序表。";return}const curriculumTargets={"校必修":Number(schoolRequiredInput.value),"院必修":Number(collegeRequiredInput.value),"專業必修":Number(majorRequiredInput.value),"專業選修":Number(majorElectiveInput.value)},id=`${workspaceOwnerEmail().replace(/[^a-z0-9]/g,"_")}_${year}_${Date.now()}`;saveCurriculumBtn.disabled=true;saveCurriculumBtn.textContent="建立中…";await setDoc(doc(db,"curricula",id),{admissionYear:year,department,program,totalCredits:Number(totalCreditsInput.value),targets:curriculumTargets,courses:[],status:"pending",sourceFileName:file.name,sourceStored:false,ownerEmail:workspaceOwnerEmail(),createdByEmail:normalizedEmail(auth.currentUser?.email),createdAt:serverTimestamp(),updatedAt:serverTimestamp()});localCurriculumPdfs.set(id,file);await loadCurricula();renderCurricula();fillCurriculumSelect();openCourseEditor(id);await prepareCurriculumPages(id,file)}catch(error){console.error(error);curriculumError.textContent="建立失敗，請確認Firestore規則已發布。"}finally{saveCurriculumBtn.disabled=false;saveCurriculumBtn.textContent="選取PDF並建立待辨識版本"}};
