async function prepareCurriculumPages(id,file){aiParseBtn.disabled=true;aiParseBtn.textContent="正在讀取頁面…";courseEditorError.textContent="正在建立PDF頁面預覽，請稍候。";try{const pdfjs=await import("https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.min.mjs");pdfjs.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.10.38/pdf.worker.min.mjs";const pdf=await pdfjs.getDocument({data:await file.arrayBuffer()}).promise;if(pdf.numPages>12)throw new Error("目前一次最多處理12頁時序表");const pages=[];for(let pageNo=1;pageNo<=pdf.numPages;pageNo++){const page=await pdf.getPage(pageNo),textContent=await page.getTextContent(),text=textContent.items.map(x=>x.str).join(" "),chinese=(text.match(/[\u4e00-\u9fff]/g)||[]).length,keywords=(text.match(/課程|學分|必修|選修|學期|一年級|二年級|三年級|四年級/g)||[]).length,viewport=page.getViewport({scale:1.6}),canvas=document.createElement("canvas"),ctx=canvas.getContext("2d");canvas.width=viewport.width;canvas.height=viewport.height;await page.render({canvasContext:ctx,viewport}).promise;const dataUrl=canvas.toDataURL("image/jpeg",.86);pages.push({pageNo,score:chinese+keywords*30,dataUrl,mimeType:"image/jpeg",data:dataUrl.split(",")[1]})}const maxScore=Math.max(...pages.map(p=>p.score));pages.forEach(p=>p.selected=maxScore===0||p.score>=Math.max(30,maxScore*.6));curriculumPdfPages.set(id,pages);renderCurriculumPages(pages);courseEditorError.textContent=maxScore===0?"無法從PDF文字判斷中文頁面，已先勾選全部，請依縮圖調整。":"已預選可能包含中文課程表的頁面，請確認勾選後按AI自動辨識。"}catch(error){console.error(error);courseEditorError.textContent=error.message||"PDF頁面讀取失敗。"}finally{aiParseBtn.disabled=false;aiParseBtn.textContent="AI自動辨識"}}
