 const detail=wb.addWorksheet("課程明細",{views:[{showGridLines:false,state:"frozen",ySplit:4}]});const detailWidths=[20,38,18,10,16,18,42];detail.columns=detailWidths.map(width=>({width}));mergeTitle(detail,"A1:G2","課程明細","FF243B53",16);detail.mergeCells("A3:G3");detail.getCell("A3").value="系統不儲存原始成績，因此此表呈現課程、學分與認列狀態。";styleExcelCell(detail.getCell("A3"),{fill:"FFFFF3D6",fontColor:"FFC8811A",align:"center"});const dh=detail.addRow(["年級／學期","課程名稱","學分類別","學分","通識領域","狀態","備註"]);dh.height=26;dh.eachCell(c=>styleExcelCell(c,{fill:"FF4E79A7",fontColor:"FFFFFFFF",bold:true,align:"center"}));(s.courses||[]).sort((a,b)=>String(a.term||"").localeCompare(String(b.term||""))).forEach(c=>{const values=[terms[c.term]||c.term||"待確認",c.name||"",c.category||"尚未分類",Number(c.credits)||0,c.domain||"",excelStatus(c),c.note||""],row=detail.addRow(values);row.eachCell((cell,col)=>styleExcelCell(cell,{align:[1,4,5,6].includes(col)?"center":"left"}));row.height=excelRowHeight(values,detailWidths)});detail.autoFilter={from:"A4",to:`G${Math.max(4,detail.lastRow.number)}`};
