async function exportStudentExcel(s){const button=[...document.querySelectorAll(".export-student")].find(b=>visibleStudentRows[Number(b.dataset.index)]===s),old=button?.textContent;try{if(button){button.disabled=true;button.textContent="製作中…"}const buffer=await buildStudentWorkbook(s);downloadBlob(new Blob([buffer],{type:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"}),`${safeFileName(s.name)}_${safeFileName(s.studentId)}_學分檢核表.xlsx`)}catch(error){console.error(error);alert(error.message||"Excel匯出失敗，請稍後再試。")}finally{if(button){button.disabled=false;button.textContent=old}}}
async function exportSelectedStudents(){const rows=allStudentRows.filter(s=>selectedStudentIds.has(s.docId));if(!rows.length)return;if(!window.JSZip){alert("批次下載元件尚未載入，請重新整理後再試。");return}const old=batchExportBtn.textContent;batchExportBtn.disabled=true;try{const zip=new JSZip();for(let i=0;i<rows.length;i++){batchExportBtn.textContent=`正在製作 ${i+1}/${rows.length}`;const s=rows[i],buffer=await buildStudentWorkbook(s);zip.file(`${safeFileName(s.name)}_${safeFileName(s.studentId)}_學分檢核表.xlsx`,buffer)}batchExportBtn.textContent="正在壓縮…";downloadBlob(await zip.generateAsync({type:"blob"}),`學生學分檢核表_批次下載_${new Date().toISOString().slice(0,10)}.zip`)}catch(error){console.error(error);alert(error.message||"批次下載失敗，請稍後再試。")}finally{batchExportBtn.disabled=false;batchExportBtn.textContent=old;updateBatchControls()}}
function openStudent(r){role=r;tab="timeline";document.querySelectorAll(".teacher-only").forEach(e=>e.classList.toggle("hidden",r!=="teacher"));document.querySelectorAll(".tab").forEach(e=>e.classList.toggle("active",e.dataset.tab==="timeline"));termFilter.value="all";detailBack.onclick=()=>show("teacherView");render();show("detailView")}
function totals(){const out=Object.fromEntries(Object.keys(targets).map(k=>[k,0]));let ext=0;recognized().forEach(c=>{let value=c.credits;if(c.external){value=Math.max(0,Math.min(value,12-ext));ext+=value}if(c.category in out)out[c.category]+=value});return out}
function render(){const t=totals(),sum=Object.values(t).reduce((a,b)=>a+b,0);studentHeader.innerHTML=`<div><h2>${student.name}</h2><p>${student.id}｜${student.department}｜${student.program}｜${student.admissionYear}學年度入學</p></div><div class="progress-total"><span>目前已取得</span><strong>${sum} 學分</strong></div>`;creditSummary.innerHTML=Object.entries(targets).map(([n,max])=>`<article class="credit-card"><h3>${n}</h3><div class="credit-numbers"><strong>${t[n]}</strong><span>／${max} 學分</span></div><div class="meter"><span style="width:${Math.min(100,t[n]/max*100)}%"></span></div></article>`).join("");renderGeneral();renderExternal();renderCourses()}
function renderGeneral(){const cs=recognized().filter(c=>c.subCategory==="分類通識"),credits=cs.reduce((n,c)=>n+c.credits,0),missing=domains.filter(d=>!cs.some(c=>c.domain===d));generalEducationSummary.innerHTML=`<section class="special-card"><div class="special-heading"><div><h3>分類通識領域檢核</h3><small>併入校必修；四領域各至少1門，再任選2門</small></div><strong>${credits}／12 學分</strong></div><div class="domain-grid">${domains.map(d=>{const count=cs.filter(c=>c.domain===d).length;return `<div class="domain-item ${count?"done":"missing"}"><strong>${d}</strong><span>${count?`已完成 ${count} 門`:"尚未完成"}</span></div>`}).join("")}</div>${missing.length?`<div class="warning-box">⚠ 尚缺領域：${missing.join("、")}</div>`:`<div class="success-box">✓ 四個領域皆已完成；目前共${cs.length}門。</div>`}</section>`}
function renderExternal(){const cs=recognized().filter(c=>c.external),total=cs.reduce((n,c)=>n+c.credits,0),used=Math.min(total,12),over=Math.max(0,total-12);externalSummary.innerHTML=`<section class="special-card external-card"><div><h3>外系學分認列</h3><p>外系課程最多認列12學分，超過部分不計入。</p>${over?`<p class="external-over">已超過${over}學分，超過部分不計入。</p>`:""}</div><div class="progress-total"><strong>${used}／12</strong><span>已認列學分${total>12?`（實修${total}）`:""}</span></div></section>`}
detailTabs.onclick=e=>{const b=e.target.closest("[data-tab]");if(!b)return;tab=b.dataset.tab;document.querySelectorAll(".tab").forEach(x=>x.classList.toggle("active",x===b));termFilter.closest("label").classList.toggle("hidden",tab==="unmatched");renderCourses()};termFilter.onchange=renderCourses;
function state(c){if(c.status==="done"||c.status==="classified")return["done",c.recognitionType==="exemption"?"已抵免／認證":"已完成",c.status==="classified"?`人工認列為${c.category}${c.external?"（外系）":""}`:""];if(c.status==="failed")return["failed","尚未完成",`曾於${c.attemptTerm}修習，但未通過`];if(c.status==="unmatched")return["pending","待人工分類",c.external?"外系課程，需人工確認認列類別":"時序表內找不到此課程"];return["missing","尚未修習",""]}
function renderCourses(){let list=student.courses;if(tab==="missing")list=list.filter(c=>["missing","failed"].includes(c.status));if(tab==="unmatched")list=list.filter(c=>c.status==="unmatched");else if(termFilter.value!=="all")list=list.filter(c=>c.term===termFilter.value);if(!list.length){courseContent.innerHTML='<div class="empty">目前沒有符合條件的課程。</div>';return}const groups=tab==="unmatched"?{"待人工分類":list}:list.reduce((o,c)=>((o[c.term]??=[]).push(c),o),{});courseContent.innerHTML=Object.entries(groups).sort(([a],[b])=>a.localeCompare(b)).map(([term,cs])=>`<section class="term-section"><h3>${terms[term]||term}</h3><table class="course-table"><thead><tr><th>課程名稱</th><th>學分類別</th><th>學分</th><th>修課狀態</th>${role==="teacher"?"<th>操作</th>":""}</tr></thead><tbody>${cs.map(c=>{const[s,l,n]=state(c),cat=c.subCategory?`${c.category}｜${c.subCategory}${c.domain?`（${c.domain}）`:""}`:(c.category||"尚未分類"),canAdjust=["done","classified","unmatched","missing"].includes(c.status),action=c.status==="missing"?"設定抵免／認證":(c.status==="unmatched"?"人工認列":"調整認列／學分");return `<tr><td data-label="課程">${c.name}${c.adjusted?'<div class="audit-note">已人工調整認列</div>':""}</td><td data-label="類別">${cat}</td><td data-label="學分">${c.credits}</td><td data-label="狀態"><span class="status ${s}">${l}</span>${n?`<div class="course-note">${n}</div>`:""}</td>${role==="teacher"?`<td data-label="操作">${canAdjust?`<button class="action-link classify" data-id="${c.id}">${action}</button>`:"—"}</td>`:""}</tr>`}).join("")}</tbody></table></section>`).join("");document.querySelectorAll(".classify").forEach(b=>b.onclick=()=>openClassify(b.dataset.id))}
classificationCategory.onchange=()=>{const schoolRequired=classificationCategory.value==="校必修";classificationDomain.disabled=!schoolRequired;if(!schoolRequired)classificationDomain.value=""};
classificationDomain.onchange=()=>{if(classificationDomain.value)classificationCategory.value="校必修"};
classificationType.onchange=updateReplacementFields;
replacementCourse.onchange=()=>{const target=student.courses.find(c=>c.id===replacementCourse.value);if(!target)return;classificationCategory.value=target.category||"專業選修";const isGeneral=target.subCategory==="分類通識"||target.name.includes("分類通識");classificationDomain.disabled=!isGeneral;if(!isGeneral)classificationDomain.value=""};
function updateReplacementFields(){const replacing=classificationType.value==="replacement",resetting=classificationType.value==="reset";replacementCourseLabel.classList.toggle("hidden",!replacing);replacementCourse.required=replacing;classificationTerm.disabled=replacing;const fieldsDisabled=classificationType.value==="excluded"||resetting;classificationCategory.disabled=fieldsDisabled;classificationCredits.disabled=fieldsDisabled;classificationDomain.disabled=fieldsDisabled||classificationCategory.value!=="校必修"}
function openClassify(id){selected=student.courses.find(c=>c.id===id);selected.wasMissing=selected.status==="missing";classifyCourseName.textContent=`${selected.name}（${selected.credits}學分）${selected.wasMissing?"｜設定為抵免／認證":""}`;classificationType.value="category";classificationCategory.value=selected.category||"專業選修";classificationCredits.value=Number(selected.credits)||0;classificationDomain.value=selected.domain||"";classificationTerm.value=selected.term||"1-1";classificationExternal.checked=!!selected.external;classificationNote.value=selected.note||"";const candidates=student.courses.filter(c=>c!==selected&&["missing","failed"].includes(c.status));replacementCourse.innerHTML='<option value="">請選擇要替代的課程</option>'+candidates.map(c=>`<option value="${escapeHtml(c.id)}">${escapeHtml(terms[c.term]||c.term)}｜${escapeHtml(c.name)}｜${c.credits}學分</option>`).join("");updateReplacementFields();classifyDialog.showModal()}
saveClassification.onclick=e=>{if(!selected)return;const credits=Number(classificationCredits.value),changingCredits=!classificationCredits.disabled;if(changingCredits&&(!Number.isFinite(credits)||credits<0||credits>9||!Number.isInteger(credits*2))){e.preventDefault();alert("認列學分請填0至9，並以0.5學分為級距。");return}if(classificationType.value==="replacement"&&!replacementCourse.value){e.preventDefault();alert("請選擇要替代的時序表課程。");return}if(classificationType.value==="reset"){if(String(selected.id).startsWith("H")){selected.status="unmatched";selected.category=null;delete selected.subCategory;delete selected.domain}else{selected.status="missing";if(selected.originalRequirement)selected.name=selected.originalRequirement;if(selected.originalCredits!==undefined)selected.credits=selected.originalCredits;delete selected.originalRequirement;delete selected.originalCredits;delete selected.recognitionType;delete selected.attemptTerm;selected.external=false}selected.term=classificationTerm.value;selected.note=classificationNote.value.trim()||"已人工取消認列";selected.adjusted=true}else if(classificationType.value==="excluded"){selected.status="excluded";selected.category=null;selected.term=classificationTerm.value;delete selected.subCategory;delete selected.domain}else if(classificationType.value==="replacement"){const target=student.courses.find(c=>c.id===replacementCourse.value);if(!target)return;const actualName=selected.name,originalName=target.name,originalCredits=target.credits;Object.assign(target,{status:"classified",name:actualName,credits,originalRequirement:originalName,originalCredits,category:classificationDomain.value?"校必修":classificationCategory.value,external:classificationExternal.checked,note:[classificationNote.value.trim(),`替代時序表課程：${originalName}`].filter(Boolean).join("；"),adjusted:true,recognitionType:"replacement",attemptTerm:selected.attemptTerm});if(classificationDomain.value){target.subCategory="分類通識";target.domain=classificationDomain.value}else{delete target.subCategory;delete target.domain}student.courses=student.courses.filter(c=>c!==selected)}else{if(selected.originalCredits===undefined&&selected.credits!==credits)selected.originalCredits=selected.credits;selected.status="classified";selected.credits=credits;selected.category=classificationCategory.value;selected.term=classificationTerm.value;if(classificationDomain.value){selected.category="校必修";selected.subCategory="分類通識";selected.domain=classificationDomain.value}else{delete selected.subCategory;delete selected.domain}if(selected.wasMissing)selected.recognitionType="exemption";selected.external=classificationExternal.checked;selected.note=classificationNote.value.trim();selected.adjusted=true}setTimeout(async()=>{render();tab="unmatched";document.querySelectorAll(".tab").forEach(t=>t.classList.toggle("active",t.dataset.tab==="unmatched"));renderCourses();if(student.docId&&auth.currentUser){try{await updateDoc(doc(db,"students",student.docId),{courses:student.courses,lastEditorEmail:normalizedEmail(auth.currentUser.email),updatedAt:serverTimestamp()})}catch(error){console.error(error);alert("畫面已調整，但儲存到 Firebase 失敗，請確認權限規則已發布。")}}},0)};
